/**
 * TopNavBar - main navigation bar at top of all pages.
 * Apple-like, simple, always visible on desktop, hamburger collapses on mobile.
 * Includes: logo/title, navigation tabs (Home, Discover, Quiz, Recommendations, Routine, Weather, Email, Geolocation, Chat)
 *
 * The Discover tab should navigate to "/all-products" (not "/products"!), per design spec.
 * 
 * Progress Tracker tab and logic will be removed in this task.
 */

function TopNavBar() {
  const location = useLocation();

  // Define tabs and target routes
  const tabs = [
    { name: "Home", to: "/" },
    { name: "Discover", to: "/all-products" },
    { name: "Quiz", to: "/quiz" },
    { name: "Recommendations", to: "/recommendations" },
    { name: "Routine", to: "/routine" },
    { name: "Weather", to: "/weather" },
    { name: "Email", to: "/email" },
    { name: "Geolocation", to: "/geolocation" },
    { name: "Chat", to: "/chat" },
    // Progress Tracker removed per requirement
  ];

  // Helper for styling active tabs
  const isActive = (path) => location.pathname === path;

  return (
    <nav className="top-navbar" style={{
      width: "100%",
      height: 70,
      background: "var(--kavia-dark)",
      color: "var(--text-color)",
      display: "flex",
      alignItems: "center",
      justifyContent: "space-between",
      padding: "0 32px",
      boxShadow: "0 2px 14px 0 rgba(40,4,40,0.09)",
      zIndex: 100,
      position: "fixed",
      top: 0,
      left: 0
    }}>
      {/* Logo / Brand */}
      <div className="navbar-logo" style={{ fontWeight: 700, fontSize: 28, letterSpacing: -1, fontFamily: "apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif" }}>
        GlowSkin
      </div>
      {/* Navigation tabs */}
      <div className="navbar-tabs" style={{ display: "flex", gap: 24 }}>
        {tabs.map(tab => (
          <Link
            key={tab.name}
            to={tab.to}
            className={`navbar-link${isActive(tab.to) ? " active" : ""}`}
            style={{
              color: isActive(tab.to) ? "var(--kavia-orange)" : "var(--text-color)",
              textDecoration: "none",
              fontWeight: isActive(tab.to) ? 600 : 400,
              borderBottom: isActive(tab.to) ? "3px solid var(--kavia-orange)" : "3px solid transparent",
              padding: "6px 16px",
              borderRadius: 10,
              background: isActive(tab.to) ? "rgba(252,222,239,0.05)" : "none",
              transition: "all 0.16s"
            }}
          >
            {tab.name}
          </Link>
        ))}
      </div>
    </nav>
  );
};

